import React from 'react';

const Results = ({ data }) => {
    if (!data || !data.title) {
        return <p>Aucun résultat disponible</p>;
    }

    return (
        <div className="quiz-content">
            <h2>Quiz Généré</h2>
            <div className="quiz-text" style={{ whiteSpace: 'pre-line' }}>
                {data.title}
            </div>
        </div>
    );
};
export default Results;
